static const char GAIT_TCN_MODEL_SHA256[] = "c0941ccb1947a686a23cf4ee12a6572389464693ef492a5d500211a29038cb9a";


namespace vspimu_tcn {
static constexpr int TIME_STEPS = 400;
static constexpr int INPUT_CHANNELS = 6;
static constexpr int FEATURES = 16;

// Tiled exact graph execution.
//
// The network's total temporal radius is 28 samples (two convolutions each
// in the 1/2/4-dilation residual blocks). We therefore process the 400-sample
// output window in independent tiles with a 28-sample input halo on each side.
// Only one full activation tile is retained; the intermediate conv output is
// streamed through a 17-slot ring. The residual skip tensor is never stored:
// its contribution is accumulated directly into the two output logits.
//
// CHUNK_STEPS controls the speed/RAM trade-off. 128 keeps the activation
// workspace small while limiting repeated halo computation.
static constexpr int CHUNK_STEPS = 128;
static constexpr int HALO_STEPS = 28;
static constexpr int LOCAL_MAX_STEPS = CHUNK_STEPS + 2 * HALO_STEPS; // 184
static constexpr int WORK_RING = 17; // enough for the d=4, pad=8 residual block

// Peak model workspace:
//   current: 184 * 16 floats = 11,776 bytes
//   ring:     17 * 16 floats =  1,088 bytes
//   total:                     12,864 bytes
// The two 400-sample output vectors and the 400x6 input remain owned by the
// firmware wrapper, so the complete TCN RAM footprint stays well below the
// previous 76.8 KB monolithic workspace.
static float* gWorkspace = nullptr;
static float* current = nullptr;
static float* workRing = nullptr;

static inline size_t workspaceBytes() {
    return ((size_t)LOCAL_MAX_STEPS * FEATURES + (size_t)WORK_RING * FEATURES) * sizeof(float);
}

// ESP32 runtime allocator: prefer byte-addressable PSRAM, then 8-bit IRAM,
// then normal internal 8-bit RAM. A plain malloc fallback keeps the header
// usable in the host parity test and on non-ESP32 targets.
static inline void* workspaceAlloc(size_t bytes) {
#if defined(ESP32) || defined(ESP_PLATFORM)
    #if defined(MALLOC_CAP_SPIRAM)
      if (void* p = heap_caps_malloc(bytes, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT)) return p;
    #endif
    #if defined(MALLOC_CAP_IRAM_8BIT)
      if (void* p = heap_caps_malloc(bytes, MALLOC_CAP_IRAM_8BIT)) return p;
    #endif
    #if defined(MALLOC_CAP_INTERNAL)
      if (void* p = heap_caps_malloc(bytes, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT)) return p;
    #endif
#endif
    return malloc(bytes);
}

static inline bool ensureWorkspace() {
    if (gWorkspace && current && workRing) return true;
    gWorkspace = (float*)workspaceAlloc(workspaceBytes());
    if (!gWorkspace) return false;
    current = gWorkspace;
    workRing = gWorkspace + (size_t)LOCAL_MAX_STEPS * FEATURES;
    return true;
}

static inline void zeroRing() {
    memset(workRing, 0, (size_t)WORK_RING * FEATURES * sizeof(float));
}

static inline void accumulateHeadLogits(float* fc, float* ic, int t, const float* branch) {
    float f = fc[t];
    float i = ic[t];
    for (int c = 0; c < FEATURES; ++c) {
        f += branch[c] * W_FC_K[c];
        i += branch[c] * W_IC_K[c];
    }
    fc[t] = f;
    ic[t] = i;
}

static inline void finalizeHeads(float* fc, float* ic, int n) {
    for (int t = 0; t < n; ++t) {
        fc[t] = 1.0f / (1.0f + expf(-(fc[t] + W_FC_B[0])));
        ic[t] = 1.0f / (1.0f + expf(-(ic[t] + W_IC_B[0])));
    }
}

static inline void storeRingVector(int localT, const float* v) {
    memcpy(workRing + (size_t)(localT % WORK_RING) * FEATURES, v, sizeof(float) * FEATURES);
}

static inline const float* ringVector(int localT) {
    return workRing + (size_t)(localT % WORK_RING) * FEATURES;
}

static inline void runBlock0(
    const float* input,
    int localN,
    float* fcLogits,
    float* icLogits
) {
    // 1x1 matching projection is the residual base for every local sample.
    for (int t = 0; t < localN; ++t) {
        for (int oc = 0; oc < FEATURES; ++oc) {
            float sum = W_B0_MATCH_B[oc];
            for (int ic = 0; ic < INPUT_CHANNELS; ++ic) {
                sum += input[(size_t)t * INPUT_CHANNELS + ic] * W_B0_MATCH_K[ic * FEATURES + oc];
            }
            current[(size_t)t * FEATURES + oc] = sum;
        }
    }

    zeroRing();
    float conv0[FEATURES];
    float branch[FEATURES];
    constexpr int PAD = 2;

    for (int t = 0; t < localN; ++t) {
        const int base = t - PAD;
        for (int oc = 0; oc < FEATURES; ++oc) {
            float sum = W_B0_CONV0_B[oc];
            for (int k = 0; k < 5; ++k) {
                const int ti = base + k;
                if (ti < 0 || ti >= localN) continue;
                for (int ic = 0; ic < INPUT_CHANNELS; ++ic) {
                    sum += input[(size_t)ti * INPUT_CHANNELS + ic]
                         * W_B0_CONV0_K[k * INPUT_CHANNELS * FEATURES + ic * FEATURES + oc];
                }
            }
            const float y = sum * W_B0_CONV0_MUL[oc] + W_B0_CONV0_SUB[oc];
            conv0[oc] = (y < 0.0f) ? 0.0f : y;
        }
        storeRingVector(t, conv0);

        const int u = t - PAD;
        if (u >= 0) {
            for (int oc = 0; oc < FEATURES; ++oc) {
                float sum = W_B0_CONV1_B[oc];
                const int b = u - PAD;
                for (int k = 0; k < 5; ++k) {
                    const int ti = b + k;
                    if (ti < 0 || ti >= localN) continue;
                    const float* src = ringVector(ti);
                    for (int ic = 0; ic < FEATURES; ++ic) {
                        sum += src[ic] * W_B0_CONV1_K[k * FEATURES * FEATURES + ic * FEATURES + oc];
                    }
                }
                branch[oc] = sum * W_B0_CONV1_MUL[oc] + W_B0_CONV1_SUB[oc];
                if (branch[oc] < 0.0f) branch[oc] = 0.0f;
            }
            accumulateHeadLogits(fcLogits, icLogits, u, branch);
            float* dst = current + (size_t)u * FEATURES;
            for (int c = 0; c < FEATURES; ++c) {
                const float y = dst[c] + branch[c];
                dst[c] = (y < 0.0f) ? 0.0f : y;
            }
        }
    }

    for (int u = localN - PAD; u < localN; ++u) {
        if (u < 0) continue;
        for (int oc = 0; oc < FEATURES; ++oc) {
            float sum = W_B0_CONV1_B[oc];
            const int b = u - PAD;
            for (int k = 0; k < 5; ++k) {
                const int ti = b + k;
                if (ti < 0 || ti >= localN) continue;
                const float* src = ringVector(ti);
                for (int ic = 0; ic < FEATURES; ++ic) {
                    sum += src[ic] * W_B0_CONV1_K[k * FEATURES * FEATURES + ic * FEATURES + oc];
                }
            }
            branch[oc] = sum * W_B0_CONV1_MUL[oc] + W_B0_CONV1_SUB[oc];
            if (branch[oc] < 0.0f) branch[oc] = 0.0f;
        }
        accumulateHeadLogits(fcLogits, icLogits, u, branch);
        float* dst = current + (size_t)u * FEATURES;
        for (int c = 0; c < FEATURES; ++c) {
            const float y = dst[c] + branch[c];
            dst[c] = (y < 0.0f) ? 0.0f : y;
        }
    }
}

static inline void runResidualBlock(
    const float* k0, const float* b0, const float* m0, const float* s0,
    const float* k1, const float* b1, const float* m1, const float* s1,
    int dilation,
    int localN,
    float* fcLogits,
    float* icLogits
) {
    const int pad = dilation * 2;
    zeroRing();
    float conv0[FEATURES];
    float branch[FEATURES];

    for (int t = 0; t < localN; ++t) {
        const int base = t - pad;
        for (int oc = 0; oc < FEATURES; ++oc) {
            float sum = b0[oc];
            for (int k = 0; k < 5; ++k) {
                const int ti = base + k * dilation;
                if (ti < 0 || ti >= localN) continue;
                for (int ic = 0; ic < FEATURES; ++ic) {
                    sum += current[(size_t)ti * FEATURES + ic]
                         * k0[k * FEATURES * FEATURES + ic * FEATURES + oc];
                }
            }
            const float y = sum * m0[oc] + s0[oc];
            conv0[oc] = (y < 0.0f) ? 0.0f : y;
        }
        storeRingVector(t, conv0);

        const int u = t - pad;
        if (u >= 0) {
            for (int oc = 0; oc < FEATURES; ++oc) {
                float sum = b1[oc];
                const int b = u - pad;
                for (int k = 0; k < 5; ++k) {
                    const int ti = b + k * dilation;
                    if (ti < 0 || ti >= localN) continue;
                    const float* src = ringVector(ti);
                    for (int ic = 0; ic < FEATURES; ++ic) {
                        sum += src[ic] * k1[k * FEATURES * FEATURES + ic * FEATURES + oc];
                    }
                }
                branch[oc] = sum * m1[oc] + s1[oc];
                if (branch[oc] < 0.0f) branch[oc] = 0.0f;
            }
            accumulateHeadLogits(fcLogits, icLogits, u, branch);
            float* dst = current + (size_t)u * FEATURES;
            for (int c = 0; c < FEATURES; ++c) {
                const float y = dst[c] + branch[c];
                dst[c] = (y < 0.0f) ? 0.0f : y;
            }
        }
    }

    for (int u = localN - pad; u < localN; ++u) {
        if (u < 0) continue;
        for (int oc = 0; oc < FEATURES; ++oc) {
            float sum = b1[oc];
            const int b = u - pad;
            for (int k = 0; k < 5; ++k) {
                const int ti = b + k * dilation;
                if (ti < 0 || ti >= localN) continue;
                const float* src = ringVector(ti);
                for (int ic = 0; ic < FEATURES; ++ic) {
                    sum += src[ic] * k1[k * FEATURES * FEATURES + ic * FEATURES + oc];
                }
            }
            branch[oc] = sum * m1[oc] + s1[oc];
            if (branch[oc] < 0.0f) branch[oc] = 0.0f;
        }
        accumulateHeadLogits(fcLogits, icLogits, u, branch);
        float* dst = current + (size_t)u * FEATURES;
        for (int c = 0; c < FEATURES; ++c) {
            const float y = dst[c] + branch[c];
            dst[c] = (y < 0.0f) ? 0.0f : y;
        }
    }
}

static inline bool predict(const float* input, float* output0, float* output1) {
    if (!input || !output0 || !output1) return false;
    if (!ensureWorkspace()) return false;

    // output0 = final-contact probabilities, output1 = initial-contact probabilities.
    for (int start = 0; start < TIME_STEPS; start += CHUNK_STEPS) {
        const int count = (start + CHUNK_STEPS <= TIME_STEPS) ? CHUNK_STEPS : (TIME_STEPS - start);
        const int wantedEnd = start + count - 1;
        const int globalInputStart = (start > HALO_STEPS) ? (start - HALO_STEPS) : 0;
        const int globalInputEnd = (wantedEnd + HALO_STEPS < TIME_STEPS) ? (wantedEnd + HALO_STEPS) : (TIME_STEPS - 1);
        const int localN = globalInputEnd - globalInputStart + 1;
        if (localN > LOCAL_MAX_STEPS) return false;

        const float* localInput = input + (size_t)globalInputStart * INPUT_CHANNELS;
        float fcLogits[LOCAL_MAX_STEPS];
        float icLogits[LOCAL_MAX_STEPS];
        memset(fcLogits, 0, sizeof(float) * localN);
        memset(icLogits, 0, sizeof(float) * localN);

        runBlock0(localInput, localN, fcLogits, icLogits);
        runResidualBlock(
            W_B1_CONV0_K, W_B1_CONV0_B, W_B1_CONV0_MUL, W_B1_CONV0_SUB,
            W_B1_CONV1_K, W_B1_CONV1_B, W_B1_CONV1_MUL, W_B1_CONV1_SUB,
            2, localN, fcLogits, icLogits
        );
        runResidualBlock(
            W_B2_CONV0_K, W_B2_CONV0_B, W_B2_CONV0_MUL, W_B2_CONV0_SUB,
            W_B2_CONV1_K, W_B2_CONV1_B, W_B2_CONV1_MUL, W_B2_CONV1_SUB,
            4, localN, fcLogits, icLogits
        );
        finalizeHeads(fcLogits, icLogits, localN);

        const int localCenter = start - globalInputStart;
        for (int j = 0; j < count; ++j) {
            const int lt = localCenter + j;
            output0[start + j] = fcLogits[lt];
            output1[start + j] = icLogits[lt];
        }
    }
    return true;
}

static inline bool predictICFC(const float* input, float* initialContact, float* finalContact) {
    return predict(input, finalContact, initialContact);
}
}

